export const getTranslatedText = (language: string, key: string): string => {
  const lang = stringsOnboarding[language as keyof typeof stringsOnboarding];
  if (!lang) {
    return stringsOnboarding.English[key as keyof typeof stringsOnboarding.English];
  }
  return lang[key as keyof typeof lang] || stringsOnboarding.English[key as keyof typeof stringsOnboarding.English];
};
